          "question": "Ao assistir uma reunião de planejamento de iteração, o gerente do projeto ouve alguns membros da equipe reclamarem que estão insatisfeitos com a distribuição de tarefas que tem sido feita nas iterações e com a maneira que outros membros da equipe os tratam. O que o gerente de projeto deve fazer?",
