          "number": 16,
          "type": "single",
          "question": "Um membro da equipe ágil recebeu certificação em uma nova ferramenta; no entanto, esse membro da equipe está reclamando que o resto da equipe não está usando a ferramenta devido à falta de conhecimento. Como o líder servidor deve aplicar inteligência emocional para alavancar essa situação em benefício do projeto?",
