          "question": "Um gerente de projeto está liderando uma equipe de desenvolvimento de software que inclui tanto especialistas altamente qualificados em áreas específicas quanto generalistas que possuem conhecimento amplo, mas menos aprofundado. Durante o projeto, o gerente percebe que, enquanto os especialistas são altamente eficientes em suas áreas, os generalistas são mais flexíveis para assumir diferentes tarefas conforme necessário. No entanto, à medida que o projeto avança, surgem desafios de colaboração, pois os especialistas preferem trabalhar de forma independente em seus domínios, enquanto os generalistas buscam um envolvimento mais amplo em várias atividades. O que o gerente pode fazer para lidar com a distração e desempenho da equipe?",
