          "number": 72,
          "type": "single",
          "question": "Durante a execução de um projeto de construção de infraestrutura rodoviária, uma nova legislação ambiental foi aprovada e impõe restrições adicionais ao uso de determinados materiais e processos de construção.\nO que o gerente de projeto deve fazer primeiro?",
