          "number": 80,
          "type": "single",
          "question": "O gerente de projetos está desenvolvendo o plano de gerenciamento das comunicações para um projeto de transformação digital em uma grande empresa. Durante uma reunião com as partes interessadas, diferentes departamentos expressam preocupações sobre a frequência das atualizações, os canais de comunicação e o nível de detalhe das informações compartilhadas. O que o gerente de projetos deve incluir no plano de gerenciamento das comunicações para garantir que as expectativas das partes interessadas sejam atendidas?",
