          "question": "Um novo projeto envolve desenvolver uma nova vacina. Um resultado de sucesso para este projeto seria criar um avanço na medicina e uma oportunidade de mercado significativa, mas há muita incerteza sobre a tecnologia e requisitos. A diretoria pediu que o gerente do projeto determine o mais rápido possível se o projeto é viável. Qual seria a melhor abordagem para fazer isso?",
