          "reference": "Guia Ágil PMI/Agile Practice Guide — capítulos sobre ciclos de vida, seleção de abordagem, entrega incremental, feedback e liderança servidora.",
          "explanation": "A resposta correta decorre da escolha da abordagem mais adequada ao grau de incerteza, estabilidade dos requisitos, necessidade de feedback e entrega de valor. Ambientes incertos favorecem ciclos adaptativos, iterativos, incrementais ou híbridos; requisitos estáveis favorecem abordagem preditiva.",
          "id": "sim1-q178",
