              "question": "Um projeto de telecomunicações está se aproximando do término e o gerente do projeto começa a trabalhar no relatório final, o qual vai fornecer um resumo do desempenho do projeto, incluindo informações sobre o atingimento dos objetivos do projeto e evidências de que os critérios de conclusão foram atendidos. Quem vai determinar se o projeto foi bem sucedido?",
