              "type": "single",
              "question": "Durante a fase de planejamento de um projeto complexo de desenvolvimento de software, o gerente de projeto decide incorporar abordagens preditivas e ágeis devido ao escopo de longo prazo do projeto e à necessidade de flexibilidade na resposta à evolução dos requisitos do cliente. O projeto tem marcos claramente definidos, mas também requer trabalho iterativo e feedback frequente das partes interessadas. O que o gerente de projeto deve fazer para combinar eficazmente as abordagens preditiva e ágil neste projeto?",
