              "question": "Uma equipe deve executar um projeto de desenvolvimento de um novo produto que tem forte concorrência no mercado e cujos custos dos insumos têm aumentado constantemente. O gerente do projeto decide usar o ciclo de vida incremental. Como o gerente do projeto deve justificar essa escolha?",
