              "question": "Um gerente de projeto é designado para um projeto que segue uma abordagem adaptativa. Após reunir todos os requisitos, o gerente de projeto visualizou de 3 a 5 releases para atingir a meta do projeto. Eles pretendem definir os detalhes de cada versão progressivamente quando obtiverem mais informações e feedback dos principais interessados. O que o gerente de projeto deve fazer, levando em consideração que o projeto tem um orçamento fixo que não pode ser excedido?",
