              "question": "Uma organização selecionou um projeto piloto para experimentar a abordagem ágil. Eles contrataram um coach ágil para ajudar o gerente de projeto, pois usavam apenas o método preditivo no passado. Durante a retrospectiva da quarta sprint, a equipe do projeto reclamou que muitos processos organizacionais estão atrapalhando o andamento do trabalho, resultando em atrasos e retrabalho no projeto. O que o gerente de projeto deve fazer?",
