              "number": 6,
              "type": "single",
              "question": "Um gerente de projetos foi solicitado a aconselhar sobre um projeto para atualizar todos os banheiros de um prédio de escritórios de vários andares com novos equipamentos de alta tecnologia e eficiência hídrica. Como o escopo e os requisitos são bem definidos desde o início, e o trabalho envolve atividades sequenciais como planejamento, demolição, instalação e testes, o gerente de projetos precisa recomendar o ciclo de vida mais adequado. Qual ciclo de vida é mais apropriado para este projeto?",
